Definition FC (Mx : word -> option byte) : Prop :=
  L5.u64_at RSEGS Mx (sp - 8) r /\ L5.u64_at RSEGS Mx (sp - 16) (bv_unsigned (getr R (reg 8))) /\ L5.u64_at RSEGS Mx (sp - 24) (bv_unsigned (getr R (reg 9))).
